import React from 'react';

const PropuestaInnovadora = () => {
    return (
        <section id="propuesta-innovadora">
            <h2>Propuesta Innovadora</h2>
            <p>
                La propuesta consiste en una campaña educativa y de sensibilización histórica denominada “Recordar para defender la democracia”, orientada a difundir de forma accesible los principales hallazgos de la investigación sobre la dictadura de los hermanos Tinoco y su impacto en la democracia costarricense.
            </p>
            <p>
                La campaña utilizaría recursos digitales y educativos como videos cortos, publicaciones en redes sociales, infografías, material para centros educativos y una línea de tiempo interactiva. El objetivo es transformar la información histórica en un producto de fácil comprensión, atractivo para las nuevas generaciones y socialmente relevante.
            </p>
            <p>
                Esta propuesta busca conectar la historia con la realidad actual, demostrando que el conocimiento del pasado fortalece la educación cívica, la memoria democrática y la participación ciudadana.
            </p>
        </section>
    );
};

export default PropuestaInnovadora;
